import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type TypewriterQuestionProps = Record<string, any>;

// Helper to generate a solid, extruded-looking 3D drop shadow
const generateHardShadow = (distance: number, color: string, scaleFactor: number) => {
  const shadowSteps = [];
  const steps = Math.floor(distance * scaleFactor);
  if (steps === 0) return "none";
  for (let i = 1; i <= steps; i++) {
    shadowSteps.push(`${i}px ${i}px 0px ${color}`);
  }
  return shadowSteps.join(", ");
};

const TypewriterQuestion: React.FC<TypewriterQuestionProps> = ({
  backgroundColor = "#FF8A5B",
  transparentBackground = false,
  durationInSeconds = 5,
  questionText = "What is\nthe best\nbreakfast\nfor weight loss?",
  textColor = "#1A1A1A",
  shadowColor = "#1A1A1A",
  shadowDistance = 12,
  framesPerCharacter = 2,
  boxColor = "#FFFDD0",
  boxBorderColor = "#1A1A1A",
  boxBorderWidth = 8,
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Staggered pop-up spring physics for 60s style thinking bubble elements
  const dot3Scale = frame >= 0 ? spring({ frame, fps, config: { damping: 10, stiffness: 120 } }) : 0;
  const dot2Scale = frame >= 4 ? spring({ frame: frame - 4, fps, config: { damping: 10, stiffness: 120 } }) : 0;
  const dot1Scale = frame >= 8 ? spring({ frame: frame - 8, fps, config: { damping: 10, stiffness: 120 } }) : 0;
  const mainBoxScale = frame >= 12 ? spring({ frame: frame - 12, fps, config: { damping: 12, stiffness: 100 } }) : 0;

  const dot3Opacity = frame >= 0 ? 1 : 0;
  const dot2Opacity = frame >= 4 ? 1 : 0;
  const dot1Opacity = frame >= 8 ? 1 : 0;
  const mainBoxOpacity = frame >= 12 ? 1 : 0;

  // Start typing the text once the main bubble is mostly popped up
  const textStartFrame = 22;

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Custom 3D pop art shadows
  const textHardShadow = generateHardShadow(shadowDistance, shadowColor, s);
  const boxHardShadow = generateHardShadow(shadowDistance * 1.5, shadowColor, s);

  // Tokenize the text to handle words, spaces, and explicit newlines safely
  // This keeps words from breaking across lines mid-typing
  const tokens = questionText.match(/(\n|\s+|\S+)/g) || [];
  let globalCharIndex = 0;

  const contentNodes = tokens.map((token, tIdx) => {
    // Handle explicit newlines
    if (token === "\n") {
      return <br key={`br-${tIdx}`} />;
    }

    // Handle whitespace chunks
    if (token.trim() === "") {
      const spaceChars = token.split("");
      return (
        <span key={`space-chunk-${tIdx}`}>
          {spaceChars.map((space, sIdx) => {
            const charIdx = globalCharIndex++;
            const isVisible = (frame - textStartFrame) >= charIdx * framesPerCharacter;
            return (
              <span
                key={`space-${charIdx}`}
                style={{
                  opacity: isVisible ? 1 : 0,
                  transition: "none",
                }}
              >
                {space}
              </span>
            );
          })}
        </span>
      );
    }

    // Handle words (wrapped in inline-block to prevent mid-word line breaks)
    const chars = token.split("");
    return (
      <span
        key={`word-${tIdx}`}
        style={{
          display: "inline-block",
          transition: "none",
        }}
      >
        {chars.map((char) => {
          const charIdx = globalCharIndex++;
          const isVisible = (frame - textStartFrame) >= charIdx * framesPerCharacter;
          return (
            <span
              key={`char-${charIdx}`}
              style={{
                opacity: isVisible ? 1 : 0,
                transition: "none",
              }}
            >
              {char}
            </span>
          );
        })}
      </span>
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* 60s Caption/Thinking Box Wrapper */}
      <div
        style={{
          position: "relative",
          width: width * 0.85,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Main Thinking Bubble */}
        <div
          style={{
            transform: `scale(${mainBoxScale})`,
            transformOrigin: "20% 90%",
            opacity: mainBoxOpacity,
            backgroundColor: boxColor,
            border: `${boxBorderWidth * s}px solid ${boxBorderColor}`,
            boxShadow: boxHardShadow,
            borderRadius: 45 * s,
            padding: `${55 * s}px ${65 * s}px`,
            width: "100%",
            boxSizing: "border-box",
            position: "relative",
            zIndex: 10,
            transition: "none",
          }}
        >
          <div
            style={{
              textAlign: "center",
              fontSize: 90 * s,
              fontWeight: 900, // Black weight to match the chunky retro pop-art style
              lineHeight: 1.15,
              letterSpacing: -2 * s,
              color: textColor,
              textShadow: textHardShadow,
              whiteSpace: "pre-wrap", // Respects both explicit \n and natural container wrapping
              wordWrap: "break-word",
            }}
          >
            {contentNodes}
          </div>
        </div>

        {/* Thinking Dot 1 (Large) */}
        <div
          style={{
            position: "absolute",
            left: "15%",
            bottom: -40 * s,
            width: 60 * s,
            height: 60 * s,
            borderRadius: "50%",
            backgroundColor: boxColor,
            border: `${boxBorderWidth * s}px solid ${boxBorderColor}`,
            boxShadow: boxHardShadow,
            transform: `scale(${dot1Scale})`,
            transformOrigin: "15% 90%",
            opacity: dot1Opacity,
            zIndex: 9,
            transition: "none",
          }}
        />

        {/* Thinking Dot 2 (Medium) */}
        <div
          style={{
            position: "absolute",
            left: "8%",
            bottom: -85 * s,
            width: 40 * s,
            height: 40 * s,
            borderRadius: "50%",
            backgroundColor: boxColor,
            border: `${boxBorderWidth * s}px solid ${boxBorderColor}`,
            boxShadow: boxHardShadow,
            transform: `scale(${dot2Scale})`,
            transformOrigin: "10% 90%",
            opacity: dot2Opacity,
            zIndex: 8,
            transition: "none",
          }}
        />

        {/* Thinking Dot 3 (Smallest) */}
        <div
          style={{
            position: "absolute",
            left: "2%",
            bottom: -120 * s,
            width: 25 * s,
            height: 25 * s,
            borderRadius: "50%",
            backgroundColor: boxColor,
            border: `${boxBorderWidth * s}px solid ${boxBorderColor}`,
            boxShadow: boxHardShadow,
            transform: `scale(${dot3Scale})`,
            transformOrigin: "5% 90%",
            opacity: dot3Opacity,
            zIndex: 7,
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default TypewriterQuestion;